(7721704, 1270991, 86447, '<td valign="top">7 from me.<br/> <br/>I love the scratches. :D</td>', '7 from me. I love the scratches. :D', '2022-06-17 14:43:55.000000', NULL, 1),
(7721760, 1271067, 83313, '<td valign="top">Has the feel of an old photo from the early 20th century. Rainy day, perhaps.</td>', 'Has the feel of an old photo from the early 20th century. Rainy day, perhaps.', '2022-06-20 13:40:59.000000', NULL, 1),
(7721761, 1271006, 83313, '<td valign="top">I see a dinosaur coming out of the brush. I think I have dinos on the brain lately.</td>', 'I see a dinosaur coming out of the brush. I think I have dinos on the brain lately.', '2022-06-20 13:41:53.000000', NULL, 1),
(7721762, 1271128, 83313, '<td valign="top">Chicago and a drone shot. Not hard to guess whose this is. Few of the regulars are anonymous after a few years here, right? Still using the Mavic air? I''ve been disappointed in the image quality from the Mini. Also got an Autel Evo, but it is bigger and doesn''t travel easily.</td>', 'Chicago and a drone shot. Not hard to guess whose this is. Few of the regulars are anonymous after a few years here, right? Still using the Mavic air? I''ve been disappointed in the image quality from the Mini. Also got an Autel Evo, but it is bigger and doesn''t travel easily.', '2022-06-20 13:46:01.000000', NULL, 1),
(7721763, 1271134, 83313, '<td valign="top">A relaxing view</td>', 'A relaxing view', '2022-06-20 13:46:32.000000', NULL, 1),
(7721968, 1271101, 65234, '<td valign="top">Just exquisite. Technical details are spot on, and it''s beautiful :-) My fave in the challenge.</td>', 'Just exquisite. Technical details are spot on, and it''s beautiful :-) My fave in the challenge.', '2022-06-22 11:26:28.000000', NULL, 1),
(7721969, 1271128, 65234, '<td valign="top">Great perspective and detail.</td>', 'Great perspective and detail.', '2022-06-22 11:26:47.000000', NULL, 1),
(7721970, 1271112, 65234, '<td valign="top">Suburbs and city, all in one image. Nicely put together, and I like the vegetative frame.</td>', 'Suburbs and city, all in one image. Nicely put together, and I like the vegetative frame.', '2022-06-22 11:27:58.000000', NULL, 1),
(7721971, 1270823, 65234, '<td valign="top">Would probably be a great landscape without the dinosaur, but I have to admit I like its inclusion.</td>', 'Would probably be a great landscape without the dinosaur, but I have to admit I like its inclusion.', '2022-06-22 11:29:00.000000', NULL, 1),
(7721972, 1270862, 65234, '<td valign="top">Great clouds and reflections framing the scene.</td>', 'Great clouds and reflections framing the scene.', '2022-06-22 11:29:36.000000', NULL, 1),
(7721973, 1270977, 65234, '<td valign="top">Toning suits the subject beautifully. Nice detail and composition.</td>', 'Toning suits the subject beautifully. Nice detail and composition.', '2022-06-22 11:30:27.000000', NULL, 1),
(7721974, 1271061, 65234, '<td valign="top">Love the long exposure. Emphasizes the stillness of the fisherman.</td>', 'Love the long exposure. Emphasizes the stillness of the fisherman.', '2022-06-22 11:32:44.000000', NULL, 1),
