(7722050, 1271112, 124815, '<td valign="top">Heroic view. Of course I like it. Only that the processing seems a little too evenly done and the "giants" might have more impact not centered.</td>', 'Heroic view. Of course I like it. Only that the processing seems a little too evenly done and the "giants" might have more impact not centered.', '2022-06-23 18:16:03.000000', NULL, 1),
(7722055, 1271101, 109227, '<td valign="top">Gorgeous and my top pick.  The tones, clarity and composition are wonderful.</td>', 'Gorgeous and my top pick.  The tones, clarity and composition are wonderful.', '2022-06-23 20:05:25.000000', NULL, 1),
(7722056, 1270862, 109227, '<td valign="top">Beautiful tones, light and composition.</td>', 'Beautiful tones, light and composition.', '2022-06-23 20:05:49.000000', NULL, 1),
(7722057, 1271128, 109227, '<td valign="top">Nicely composed, great clarity and tones.</td>', 'Nicely composed, great clarity and tones.', '2022-06-23 20:06:22.000000', NULL, 1),
(7722058, 1271067, 109227, '<td valign="top">Beautiful.</td>', 'Beautiful.', '2022-06-23 20:06:51.000000', NULL, 1),
(7722067, 1271006, 24454, '<td valign="top">There''s something about this that I like so much.  The hazy mythical feel.  the way that tree forms an arch like a gateway to another place.  I can see it hanging on a wall.  Good luck!</td>', 'There''s something about this that I like so much.  The hazy mythical feel.  the way that tree forms an arch like a gateway to another place.  I can see it hanging on a wall.  Good luck!', '2022-06-23 23:57:12.000000', NULL, 1),
(7722068, 1270862, 24454, '<td valign="top">So dramatic!  I can feel what it must feel like to be in that scene.</td>', 'So dramatic!  I can feel what it must feel like to be in that scene.', '2022-06-23 23:58:10.000000', NULL, 1),
(7722069, 1270823, 24454, '<td valign="top">So interesting!  The clouds look like the dinosaur''s breath blowing forth on the land.  I like it  :)</td>', 'So interesting!  The clouds look like the dinosaur''s breath blowing forth on the land.  I like it  :)', '2022-06-23 23:59:30.000000', NULL, 1),
(7722070, 1271064, 24454, '<td valign="top">Oh how beautiful!  I bet it takes your breath away in person!</td>', 'Oh how beautiful!  I bet it takes your breath away in person!', '2022-06-24 00:00:13.000000', NULL, 1),
(7722071, 1270977, 24454, '<td valign="top">Ohmy!  How beautiful!</td>', 'Ohmy!  How beautiful!', '2022-06-24 00:02:25.000000', NULL, 1),
(7722072, 1271079, 24454, '<td valign="top">I''ve been there!  It''s amazing!  And the eagle!  It gives such justice to the striking scene!</td>', 'I''ve been there!  It''s amazing!  And the eagle!  It gives such justice to the striking scene!', '2022-06-24 00:03:51.000000', NULL, 1),
(7722073, 1271077, 24454, '<td valign="top">This is so striking!  I love how dramatic my initial reaction was when I opened it.</td>', 'This is so striking!  I love how dramatic my initial reaction was when I opened it.', '2022-06-24 00:05:05.000000', NULL, 1),
(7722074, 1271085, 24454, '<td valign="top">How lovely!  It feels so serene.  Like a secret private place I''d love to sit and just be!</td>', 'How lovely!  It feels so serene.  Like a secret private place I''d love to sit and just be!', '2022-06-24 00:06:12.000000', NULL, 1),
(7722075, 1271101, 24454, '<td valign="top">Wow!  I''ve only voted on 17 so far... but this!  If it were me giving ribbons, so far, this one would far and above get the blue!  It''s stunning!</td>', 'Wow!  I''ve only voted on 17 so far... but this!  If it were me giving ribbons, so far, this one would far and above get the blue!  It''s stunning!', '2022-06-24 00:07:27.000000', NULL, 1),
(7722076, 1271067, 24454, '<td valign="top">This is beautiful.  I love how it is so tack sharp where it needs to be, and so ethereal and dreamy in other places.</td>', 'This is beautiful.  I love how it is so tack sharp where it needs to be, and so ethereal and dreamy in other places.', '2022-06-24 00:08:15.000000', NULL, 1),
(7722077, 1271095, 24454, '<td valign="top">Such beautiful contrasts!  Very much like an Ansel Adams even if there are no mountains.</td>', 'Such beautiful contrasts!  Very much like an Ansel Adams even if there are no mountains.', '2022-06-24 00:09:07.000000', NULL, 1),
(7722078, 1270869, 24454, '<td valign="top">I love this with the moon (or is that the sun??)  The contrasting lights and darks are exquisite.</td>', 'I love this with the moon (or is that the sun??)  The contrasting lights and darks are exquisite.', '2022-06-24 00:10:23.000000', NULL, 1),
(7722079, 1271061, 24454, '<td valign="top">Ohmygoodness!  Fabulous!  My second 10!  I hope to see you in the winners'' circle in a few minutes!</td>', 'Ohmygoodness!  Fabulous!  My second 10!  I hope to see you in the winners'' circle in a few minutes!', '2022-06-24 00:11:33.000000', NULL, 1),
(7722080, 1271100, 24454, '<td valign="top">This is so good!  Such beautiful contrasts without being overdone or harsh!</td>', 'This is so good!  Such beautiful contrasts without being overdone or harsh!', '2022-06-24 00:12:20.000000', NULL, 1),
(7722081, 1271077, 173844, '<td valign="top">Both flat and severe, yet sumptuous. A simple image of emotional depth.<br/>One of three personal co-favorites.</td>', 'Both flat and severe, yet sumptuous. A simple image of emotional depth.One of three personal co-favorites.', '2022-06-24 00:16:23.000000', NULL, 1),
(7722082, 1271126, 173844, '<td valign="top">Nicely captured night rain.  As a landscape it seems cramped, but as an evocation of a particular mood and moment in time, it shines.<br/>One of three personal co-favorites.</td>', 'Nicely captured night rain.  As a landscape it seems cramped, but as an evocation of a particular mood and moment in time, it shines.One of three personal co-favorites.', '2022-06-24 00:19:36.000000', NULL, 1),
(7722083, 1271064, 173844, '<td valign="top">So this is the floating world?  See that monk wandering a byway?  These are the textures of serenity.<br/>One of three personal co-favorites.</td>', 'So this is the floating world?  See that monk wandering a byway?  These are the textures of serenity.One of three personal co-favorites.', '2022-06-24 00:25:37.000000', NULL, 1),
